<article class="panel" id="batch-<?= (int)$batch['id'] ?>"><div class="row"><span class="badge <?= e($batch['status']) ?>"><?= e(statusText($batch['status'])) ?></span><span class="muted"><?= e($batch['delivery_format']) ?></span></div><h2 style="margin-top:18px"><?= e($batch['title']) ?></h2><dl class="meta-list"><div><dt>Tanggal</dt><dd><?= e($batch['start_date'].' — '.$batch['end_date']) ?></dd></div><div><dt>Lokasi</dt><dd><?= e($batch['location']?:'Belum diumumkan') ?></dd></div><div><dt>Batas pendaftaran (WIB)</dt><dd><?= e($batch['registration_deadline']?:'Belum diumumkan') ?></dd></div><div><dt>Sisa kuota</dt><dd><?= $batch['status']==='confirmed'&&$batch['capacity']!==null?max(0,(int)$batch['capacity']-(int)$batch['reserved']).' peserta':'Belum diumumkan' ?></dd></div><div><dt>Biaya</dt><dd><?= e($batch['status']==='confirmed'?rupiah($batch['price']):'Belum diumumkan') ?></dd></div></dl><?php if($batch['status']==='proposed'): ?><p class="muted">Tanggal masih berupa usulan. Mengirim minat tidak mengunci kursi atau memastikan pelaksanaan.</p><?php endif; ?><div class="actions"><?php if(batchOpen($batch)): ?><a class="btn" href="enroll.php?batch=<?= (int)$batch['id'] ?>">Daftar pelatihan</a><?php else: ?><a class="btn secondary" href="contact.php?type=public&amp;program=<?= e($batch['program_slug']) ?>">Kirim daftar minat</a><?php endif; ?><a class="btn secondary" href="program.php?program=<?= e($batch['program_slug']) ?>">Detail program</a></div></article>
